// The parse tree of a finished parse, from the nonterminal node that spans the input.
pub fn create_parse_tree<'a>(
    root_id: SPPFNodeId,
    parser: &ExceptNonterminalParser,
    builder: &ExceptNonterminalParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    let iguana_runtime::sppf::SPPFNode::Nonterminal(root) =
        iguana_runtime::parser::Parser::sppf_node(parser, root_id)
    else {
        panic!("the SPPF root is not a nonterminal node")
    };
    match root.nonterminal_id {
        grammar::S => ParseTree::S(visit_sppf(root_id, parser, builder).unwrap_one().unwrap_s()),
        grammar::ID => ParseTree::Id(
            visit_sppf(root_id, parser, builder)
                .unwrap_one()
                .unwrap_id(),
        ),
        grammar::NAME => ParseTree::Name(
            visit_sppf(root_id, parser, builder)
                .unwrap_one()
                .unwrap_name(),
        ),
        grammar::START_S => ParseTree::StartS(
            visit_sppf(root_id, parser, builder)
                .unwrap_one()
                .unwrap_start_s(),
        ),
        grammar::START_ID => ParseTree::StartId(
            visit_sppf(root_id, parser, builder)
                .unwrap_one()
                .unwrap_start_id(),
        ),
        grammar::START_NAME => ParseTree::StartName(
            visit_sppf(root_id, parser, builder)
                .unwrap_one()
                .unwrap_start_name(),
        ),
        _ => panic!(),
    }
}
